&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;6&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;header&quot;&gt;Act as&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;header&quot;&gt;architectural&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;header&quot;&gt;&amp;nbsp;liaison across AI&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;header&quot;&gt;CoE&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;header&quot;&gt;, Development, DevOps, Infrastructure, Systems, Network, and Security; mentor engineers and own the platform roadmap.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[4680,9360],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[3,4]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
